REPLACE INTO `cscart_addon_descriptions` VALUES ('age_verification','年龄核实','切换年龄限制规则的产品和分类','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('anti_fraud','反欺诈','增加配置安全订单的核查使用maxmind服务来防止欺诈','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('attachments','附件','可以将文件附加到产品','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('banners','横幅管理','允许您创建文本和形象的横幅','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('barcode','订单条码','可以配置和附加条码到订单','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('bestsellers','畅销','可以收集最畅销产品的数据,并添加产品块的填充类型来展现他们','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('buy_together','一起购买','允许您对某些产品组合设置共享折扣','zh');
