REPLACE INTO `cscart_addon_descriptions` VALUES ('data_feeds','数据源','可以在CVS中创建产品数据源','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('discussion','点评和评论','让客户留下对产品,分类,订单等的评论,产品评论和撰写推荐','zh');
REPLACE INTO `cscart_addon_descriptions` VALUES ('form_builder','表单生成器','允许您自定义表单(如. 联系我们或是申请合作)','zh');
