REPLACE INTO `cscart_page_descriptions` VALUES (1,'zh','Our team','<p>\n\n  Мы рады познакомить вас с сотрудниками нашей компании. Это именно те люди, которые каждый день с любовью подбирают ассортимент интернет-магазина, консультируют вас на этапе выбора товара и общаются с вами при покупке. Это те, кто оформляет ваш заказ и заботится о надежной доставке.\n\n</p>\n\n<p>\n\n	<br>\n\n   Мы гордимся работой каждого!\n\n</p>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (2,'zh','About our company','<div class=\"ty-list-container\">\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-blue-light ty-header\"><br>\n\n				<span class=\"ty-big\">2006</span></span>The year of company foundation\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-blue-light ty-header\">more than<br>\n\n				<span class=\"ty-big\">150 000</span></span>goods we have sold\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-blue-light ty-header\"><br>\n\n				<span class=\"ty-big\">72%</span></span>of clients do repeat purchases in our store\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-blue-light ty-header\"><br>\n\n				<span class=\"ty-big\">4,2</span></span>our rating at the <a href=\"http://market.yandex.ru/\" class=\"ty-blue-light ty-underline\">Yandex Market</a>\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-blue-light ty-header\">more than<br>\n\n				<span class=\"ty-big\">25000</span></span>clients\n\n			</div>\n\n		</div>\n\n	</div>\n\n</div>\n\n<div class=\"ty-promo-container\" style=\"margin: 55px 0;\">\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-promo-image\">\n\n			<img src=\"images/companies/1/pages/people/Staff-CS-Cart-01.jpg\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-promo-description\">\n\n			<p>\n\n                We do work for you!\n\n				<br>\n\n			</p>\n\n			<p>\n\n                And that’s not just words :-)\n\n			</p>\n\n		</div>\n\n	</div>\n\n</div>\n\n<h2 class=\"ty-main-title2\">Our team</h2>\n\n<div class=\"ty-list-container with-shadow\">\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-136.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Pavel Alexeev</span> CEO\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-096.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Maksim Kiselev</span> Supplier relationship manager\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-120.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Nikolay Filimonov</span> Marketing director\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-111.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Ekaterina Matveeva</span> Head of call-center\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-116.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Maxim Fadeev</span> Logistician\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-051.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Arnold Einstein\n\n				</span> Call-center operator\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-033.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Mariya Kaveeva</span> Call-center operator\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-081.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Bruce Willis</span> Call-center operator\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-064.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Ivan Perspectivov</span> Courier\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n			<div class=\"ty-list-image ty-left\">\n\n				<img src=\"images/companies/1/pages/people/Staff-CS-Cart-173.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text\">\n\n				<span class=\"ty-list-header\">Marat Kivanin</span> Courier\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-company__item\">\n\n		</div>\n\n	</div>\n\n</div>\n\n<div class=\"ty-about-container\">\n\n	<div class=\"ty-about-content\">\n\n		<h2 class=\"ty-main-title\">Company details</h2>\n\n		<div class=\"ty-list-container\">\n\n			<div class=\"ty-column3\">\n\n                LLC Demonstration Store\n\n				<br>\n\n				<br>\n\n                TIN: 433000000000\n\n				<br>\n\n                RVC: 775000000\n\n				<br>\n\n                PSRN: 1067000000000\n\n				<br>\n\n                CEO: Alexeev Pavel Ivanovich\n\n				<br>\n\n			</div>\n\n			<div class=\"ty-column3\">\n\n				<br>\n\n				<br>\n\n                The name of the bank: JSC VTB Bank, Moscow\n\n				<br>\n\n                BIC: 044525187\n\n				<br>\n\n                Correspondent account: 30101810700000000000\n\n				<br>\n\n                Current account: 40702810500110000000\n\n				<br>\n\n			</div>\n\n		</div>\n\n	</div>\n\n</div>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (3,'zh','Privacy policy','<h3>What information do we collect?</h3>\n<p>We collect information from you when you register on our site, place an order, subscribe to our newsletter or fill out a form.</p>\n<p>When ordering or registering on our site, as appropriate, you may be asked to enter your: name, e-mail address or mailing address. You may, however, visit our site anonymously.</p>\n<p>&nbsp;</p>\n<h3>What do we use your information for?</h3>\n<p>Any of the information we collect from you may be used in one of the following ways:</p>\n<ul>\n<li>To personalize your experience<br /> (your information helps us to better respond to your individual needs)</li>\n<li>To improve our website<br /> (we continually strive to improve our website offerings based on the information and feedback we receive from you)</li>\n<li>To improve customer service<br /> (your information helps us to more effectively respond to your customer service requests and support needs)</li>\n<li>To process transactions\n<ul>\n<li>Your information, whether public or private, will not be sold, exchanged, transferred, or given to any other company for any reason whatsoever, without your consent, other than for the express purpose of delivering the purchased product or service requested.</li>\n</ul>\n</li>\n<li>To administer a contest, promotion, survey or other site feature</li>\n<li>To send periodic emails<br />\n<ul>\n<li>The email address you provide for order processing, may be used to send you information and updates pertaining to your order, in addition to receiving occasional company news, updates, related product or service information, etc.</li>\n</ul>\nNote: If at any time you would like to unsubscribe from receiving future emails, we include detailed unsubscribe instructions at the bottom of each email.</li>\n</ul>\n<p>&nbsp;</p>\n<h3>How do we protect your information?</h3>\n<p>We implement a variety of security measures to maintain the safety of your personal information when you place an order or enter, submit, or access your personal information.</p>\n<p>We offer the use of a secure server. All supplied sensitive information is transmitted via Secure Socket Layer (SSL) technology and then encrypted into our Payment gateway providers database only to be accessible by those authorized with special access rights to such systems, and are required to keep the information confidential.</p>\n<p>&nbsp;</p>\n<h3>Do we use cookies?</h3>\n<p>Yes (Cookies are small files that a site or its service provider transfers to your computers hard drive through your Web browser (if you allow) that enables the sites or service providers systems to recognize your browser and capture and remember certain information).</p>\n<p>We use cookies to help us remember and process the items in your shopping cart, understand and save your preferences for future visits and keep track of advertisements.</p>\n<p>&nbsp;</p>\n<h3>Do we disclose any information to outside parties?</h3>\n<p>We do not sell, trade, or otherwise transfer to outside parties your personally identifiable information. This does not include trusted third parties who assist us in operating our website, conducting our business, or servicing you, so long as those parties agree to keep this information confidential. We may also release your information when we believe release is appropriate to comply with the law, enforce our site policies, or protect ours or others rights, property, or safety. However, non-personally identifiable visitor information may be provided to other parties for marketing, advertising, or other uses.</p>\n<p>&nbsp;</p>\n<h3>Third party links</h3>\n<p>Occasionally, at our discretion, we may include or offer third party products or services on our website. These third party sites have separate and independent privacy policies. We therefore have no responsibility or liability for the content and activities of these linked sites. Nonetheless, we seek to protect the integrity of our site and welcome any feedback about these sites.</p>\n<p>&nbsp;</p>\n<h3>Online Privacy Policy Only</h3>\n<p>This online privacy policy applies only to information collected through our website and not to information collected offline.</p>\n<p>&nbsp;</p>\n<h3>Your Consent</h3>\n<p>By using our site, you consent to our privacy policy.</p>\n<p>&nbsp;</p>\n<h3>Changes to our Privacy Policy</h3>\n<p>If we decide to change our privacy policy, we will post those changes on this page, and/or update the Privacy Policy modification date below.</p>\n<p>This policy was last modified on 01.12.2012</p>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (6,'zh','Low price guarantee','<p>We guarantee the lowest prices on the products presented in our store.</p><p>If you find a lower price for any of our products, offered by a designated online retailer, save the link and contact us.</p><p>After we verify that our competitor\'s price is more attractive, we will lower ours to be at least as low!</p>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (19,'zh','Why gift certificate is the best present nowadays','\n\n<div class=\"ty-list-container clearfix\">\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-gift-certificate__item\">\n\n			<div class=\"ty-list-image\" style=\"margin-bottom: 15px;\">\n\n				<img src=\"images/companies/1/pages/gift1.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\" style=\"padding-top: 0;\">\n\n                    How often do you face the issue of choosing presents for friends?\n\n				<br>\n\n                If there are not so many problems with choosing presents for friends (as you know their habits and preferences), it’s much more complicated with presents for people you know less.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-gift-certificate__item\">\n\n			<div class=\"ty-list-image\" style=\"margin-bottom: 15px;\">\n\n				<img src=\"images/companies/1/pages/gift2.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\" style=\"padding-top: 0;\">\n\n                   There is hardly such a person who wants their present to be put in a cupboard and get dusty, until someone throws it away during thorough cleaning or gives someone else as a present.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-gift-certificate__item\">\n\n			<div class=\"ty-list-image\" style=\"margin-bottom: 15px;\">\n\n				<img src=\"images/companies/1/pages/gift3.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\" style=\"padding-top: 0;\">\n\n                   The present doesn’t just show care, but it also reminds of the one, who gave it.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-gift-certificate__item\">\n\n			<div class=\"ty-list-image\" style=\"margin-bottom: 15px;\">\n\n				<img src=\"images/companies/1/pages/gift4.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\" style=\"padding-top: 0;\">\n\n                   Present your friend a gift certificate of our store and you can be sure that they will choose a present to his liking and will remember your care!\n\n			</div>\n\n		</div>\n\n	</div>\n\n</div>\n\n<div style=\"margin-bottom: 40px;\" class=\"ty-buttons-container ty-main-buttons ty-center\">\n\n	<a href=\"index.php?dispatch=gift_certificates.add\" class=\"ty-btn__primary ty-btn__big ty-btn\">Buy gift certificate</a>\n\n</div>\n\n','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (20,'zh','Contacts','<div class=\"ty-column4\">\n\n		<div class=\"ty-pages-contacts__contact-block\">\n\n			<h4>\n\n                Address:\n\n			</h4>\n\n			<div>\n\n                Apt. 1, the 1st Dubrovskaya St., office 100\n\n				<br>\n\nMoscow, Russia\n\n			</div>\n\n			<h4>\n\n                Email:\n\n			</h4>\n\n			<div>\n\n				<a href=\"mailto:sales@demostore.ru\">sales@demostore.ru</a>\n\n			</div>\n\n			<h4>\n\n                Phone number:\n\n			</h4>\n\n			<div>\n\n                8-800-0000-00-00\n\n			</div>\n\n			<div>\n\n                (call is free)\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4 ty-float-right ty-notice\">\n\n		<div>\n\n			<h5>\n\n                Working hours of the online store consultants:\n\n			</h5>\n\n			<p>\n\n                10:00 &mdash; 18:00\n\n			</p>\n\n			<p>\n\n                (Moscow time)\n\n			</p>\n\n			<p>\n\n                Monday - Friday\n\n			</p>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column1\">\n\n		<iframe src=\"https://yandex.ru/map-widget/v1/?um=constructor%3A3a4ee5d803510b9547d759a3fd100125020b32d9139309eae0f421d9995921bc&source=constructor\" width=\"100%\" height=\"400\" frameborder=\"0\" style=\"border:0\" allowfullscreen></iframe>\n\n	</div>\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-pages-contacts__image\">\n\n			<img src=\"images/companies/1/pages/office.jpg\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column2\">\n\n		<div>\n\n			<h3 class=\"ty-pages-contacts__office-title\">\n\n			How to get to us\n\n			</h3>\n\n			<p class=\"ty-pages-contacts__office-instruction\">\n\n                Proletarskaya metro station. The last carriage from the center. Turn right after the glass doors. Turn left on the stairs. Go along the brick building towards the center, go past banks and the stadium under construction, at the end of the building turn right. After 200 metres turn left. That is the 1st Dubrovskaya street. Go along the street until you see the Demo Store sign-board. Enter the doors under this sign-board, go down the stairs, office 100.\n\n			</p>\n\n		</div>\n\n	</div>\n\n</div>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (21,'zh','Exchange and return','<div class=\"ty-list-container ty-decimal\">\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-refund__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/refund_b1.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n				<span class=\"ty-list-item\">1</span>Carefully pack the goods in the original wrapper as a complete set (goods sold as sets should be returned in sets).\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-refund__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/refund_b2.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n				<span class=\"ty-list-item\">2</span>Fill in an application for return attached to the order.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-refund__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/refund_b3.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n				<span class=\"ty-list-item\">3</span>Attach a copy of the cashier\'s receipt, define the method of refund (postal order or transfer to the bank account).\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-refund__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/refund_b4.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n				<span class=\"ty-list-item\">4</span>Post the parcel to the address:<br>\n\n170000, LLC Demo Store, Moscow.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-refund__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/refund_b5.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n				<span class=\"ty-list-item\">5</span>After you have sent the parcel, please inform us of that by sending an email to <a href=\"mailto:sales@demostore.ru\">sales@demostore.ru</a>.\n\n			</div>\n\n		</div>\n\n	</div>\n\n</div>\n\n<h2 class=\"ty-main-title\">Reasons for goods return and exchange</h2>\n\n<div class=\"ty-list-container\">\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-list-image\">\n\n			<img src=\"images/companies/1/pages/refund_2week.jpg\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-list-text big\">\n\n            Customer has a right to return the Goods (The Goods can be returned in case it was not used, its consumer properties, factory labels and its ready sale appearance are reserved) without defining the reason during\n\n			<span class=\"ty-red\">14 (fourteen) calendar days</span> from the moment of the actual Goods delivery from the Seller or people, representing the Seller.\n\n			<br>\n\n			<br>\n\n                              No.55 Decree of the the Government of the Russian Federation of 19th January 1998 approved “The list of non-food goods of proper quality not to be returned or exchanged for the analogous Goods of different size, shape, style”.\n\n			<br>\n\n			<br>\n\n                       This list points that Goods of proper quality, that possess individual properties, can not be returned if such Goods can be used only by the consumer who buys it.\n\n			<br>\n\n			<br>\n\n                        To return the goods, you have to submit the document proving the fact and conditions of its purchase, and fill in the application for the goods return.\n\n			<br>\n\n			<br>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column3-1\">\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-list-image\">\n\n			<img src=\"images/companies/1/pages/refund_defact.jpg\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-list-text big\">\n\n            The Goods return in case of the discovery of defects, related to the failure to meet the conditions of the Order, happened at the Seller’ fault:\n\n			<br>\n\n			<br>\n\n                      In case the Goods was given to you with partial non-observance or violation of the Order terms at the Seller’s fault, concerning the assortment, completeness, amount of Goods, you are entitled to inform the Seller (not later than\n\n			<span class=\"ty-red\">seven calendar days</span> after the Goods is received) about the violations and demand to rectify them.\n\n			<br>\n\n			<br>\n\n                     You also have the right to refuse to take goods and ask for money refund. In this case the goods must be returned to the Seller with the preservation of the original sale appearance, consumer properties, seals, factory labels.\n\n			<br>\n\n			<br>\n\n                       To return the goods, you have to submit the document proving the fact and conditions of its purchase, and fill in the application for the goods return.\n\n			<br>\n\n			<br>\n\n		</div>\n\n	</div>\n\n</div>\n\n<div class=\"ty-about-container ty-flag-left ty-list-container\">\n\n	<div class=\"ty-notice clearfix\">\n\n		<div class=\"ty-about-banner ty-column7\">\n\n			<img src=\"images/companies/1/pages/about_flag.png\">\n\n		</div>\n\n		<div class=\"ty-about-description ty-column2 ty-list-text big\">\n\n			<p>\n\n                You can see the full version of the Law on the consumers rights and receive professional advice at the following link:\n\n			</p>\n\n			<p>\n\n				<a href=\"http://ozpp.ru/laws/zpp.php\" class=\"ty-blue\">http://ozpp.ru/laws/zpp.php</a>\n\n			</p>\n\n		</div>\n\n	</div>\n\n</div>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (22,'zh','Payment and shipping','<div class=\"ty-list-container\">\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/delivery_calc.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                The cost and delivery time of your order are estimated online on the checkout.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/delivery_calc_w_ru.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                The estimation is done according to the goods weight and point of destination.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/delivery_ship.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                We deliver orders to any settlement of Russia and 230 countries all over the world.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n		</div>\n\n	</div>\n\n</div>\n\n<div class=\"ty-column1\" style=\" background-color: #ffee3c; padding-top:30px;\">\n\n	<div class=\"clearfix\">\n\n		<div class=\"ty-column7\" style=\" text-align: center; \">\n\n			<img src=\"images/companies/1/pages/delivery_car.jpg\">\n\n		</div>\n\n		<div class=\"ty-column2\">\n\n			<p>\n\n                 If your order total amounts to\n\n			</p>\n\n			<p style=\"font-size: 2em; padding: 0px;\">\n\n                3000 rubles or more,\n\n			</p>\n\n			<p class=\"subheader\">\n\n                we will deliver your order to any town of Russia or CIS\n\n			</p>\n\n			<h2 class=\"ty-uppercase\" style=\"margin: 0px;\">FOR FREE</h2>\n\n		</div>\n\n	</div>\n\n</div>\n\n<h2 class=\"ty-main-title2\">Shipping methods</h2>\n\n<div class=\"ty-list-container\">\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/delivery_person.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                Courier delivery (only within the MKAD road)\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/delivery_own.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                You can also receive your order in one of Customer\n\n				<a class=\"ty-underline ty-blue-light2\" href=\"index.php?dispatch=store_locator.search\">Pick Up Centers</a>\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column4\">\n\n		<div class=\"ty-delivery__item\">\n\n		</div>\n\n	</div>\n\n</div>\n\n<h3 class=\"ty-main-title2\">Shipping via the most popular and trustworthy companies</h3>\n\n<div class=\"ty-items-container\">\n\n	<img src=\"images/companies/1/pages/d_companies_postru.jpg\" class=\"item\"> <img src=\"images/companies/1/pages/d_companies_emsru.jpg\" class=\"item\"> <img src=\"images/companies/1/pages/d_companies_cdek.jpg\" class=\"item\">\n\n</div>\n\n<h2 style=\"padding-top: 60px\" class=\"ty-main-title\">Payment</h2>\n\n<div class=\"ty-list-container\">\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/payment_person.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                Pay the courier when delivered (only within the MKAD road)\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/payment_ccard.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                Credit card. You can pay your order with a VIsa or Master Visa card when the order is placed in our store or when receiving the goods. The courier has the terminal.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/payment_sbrf.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                Payment via the Sberbank receipt. To pay, you should print and pay the receipt of the Russian Sberbank and then send us the scanned copy of the received payment document to our email\n\n				<a href=\"mailto:sales@demostore.ru\">sales@demostore.ru</a>.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/payment_bill.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                Non-cash settlements (invoices). This method is best for organisations. You place an order, print the received invoice, pay it, and contact us to know the order delivery date.\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column5\">\n\n		<div class=\"ty-delivery__item\">\n\n			<div class=\"ty-list-image\">\n\n				<img src=\"images/companies/1/pages/payment_mobile.jpg\">\n\n			</div>\n\n			<div class=\"ty-list-text big\">\n\n                 Payment via mobile phone\n\n			</div>\n\n		</div>\n\n	</div>\n\n</div>\n\n<h3 class=\"ty-main-title2\">We also accept payments via the most popular online payment methods in Russia</h3>\n\n<div class=\"ty-items-container\">\n\n	<img src=\"images/companies/1/pages/payment_qiwi.jpg\" class=\"item\"> <img src=\"images/companies/1/pages/payment_webmoney.jpg\" class=\"item\"> <img src=\"images/companies/1/pages/payment_yamoney.jpg\" class=\"item\">\n\n</div>\n\n<div style=\"padding: 48px 0 48px; height: 1px;\">\n\n</div>','','','','');
REPLACE INTO `cscart_page_descriptions` VALUES (23,'zh','Pay in rewards points and save money','<div class=\"ty-content-reward-points__general\">\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-content-reward-points__product-img\">\n\n			<img class=\"ty-image\" src=\"images/companies/1/pages/reward-points-1.jpg?1411987227278\">\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column2\">\n\n		<div class=\"ty-column1 ty-notice\">\n\n			<p>\n\n				When you purchase goods in our store, you get reward points.\n\n			</p>\n\n			<p>\n\n				Saved reward points remain with you forever; we think that they shouldn’t burn down and we don’t define any periods when they can be used (as most of our competitors do).\n\n			</p>\n\n		</div>\n\n		<div class=\"ty-column1\">\n\n			<h3>See the balance of your bonus account</h3>\n\n			<div>\n\n				<img class=\"ty-image\" class=\"ty-image\" src=\"images/companies/1/pages/reward-points-3.jpg\">\n\n			</div>\n\n		</div>\n\n	</div>\n\n	<div class=\"ty-column1 ty-notice\">\n\n\n\n			<h3>Use reward points</h3>\n\n			<div class=\"ty-content-reward-points__checkout-img\">\n\n				<img src=\"images/companies/1/pages/reward-points-2.jpg?1411987239281\">\n\n			</div>\n\n			<div class=\"ty-column1\">\n\n				<p><br>\n\n		At checkout you should insert the reward points you have in the “Reward points” fields, and the cost of your purchase will be automatically recalculated.\n\n				</p>\n\n			</div>\n\n  </div>','','','','');
